param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
$assembly=[Reflection.Emit.AssemblyBuilder]::DefineDynamicAssembly([Reflection.AssemblyName]::new('Utf8EqualityOracle'),[Reflection.Emit.AssemblyBuilderAccess]::Run);$module=$assembly.DefineDynamicModule('Utf8EqualityOracle');$builder=$module.DefineType('DerivedUtf8',[Reflection.TypeAttributes]::Public,[Text.UTF8Encoding]);$ctor=$builder.DefineConstructor([Reflection.MethodAttributes]::Public,[Reflection.CallingConventions]::Standard,[type[]]@([bool],[bool]));$il=$ctor.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_2);$il.Emit([Reflection.Emit.OpCodes]::Call,[Text.UTF8Encoding].GetConstructor([type[]]@([bool],[bool])));$il.Emit([Reflection.Emit.OpCodes]::Ret);$derived=$builder.CreateType()
$values=[Collections.Generic.List[Text.Encoding]]::new();$profiles=@();$templates=@(@(),@(63),@(65,66),@(0xfffd),@(0xd800,0xdc00))
foreach($emit in @($false,$true)){foreach($strict in @($false,$true)){foreach($kind in @('base','derived')){
 $e=if($kind -eq 'base'){[Text.UTF8Encoding]::new($emit,$strict)}else{[Activator]::CreateInstance($derived,[object[]]@($emit,$strict))};$values.Add($e);$profiles+=[ordered]@{kind=$kind;emit=$emit;strict=$strict;encoder=-1;decoder=-1}
}}}
$values.Add([Text.Encoding]::UTF8);$profiles+=[ordered]@{kind='default';emit=$true;strict=$false;encoder=-1;decoder=-1}
$values.Add([Text.Encoding]::UTF8.Clone());$profiles+=[ordered]@{kind='defaultClone';emit=$true;strict=$false;encoder=-1;decoder=-1}
foreach($emit in @($false,$true)){foreach($encoder in 0..5){foreach($decoder in 0..5){
 $e=[Text.Encoding]([Text.UTF8Encoding]::new($emit)).Clone();$e.EncoderFallback=if($encoder -eq 5){[Text.EncoderExceptionFallback]::new()}else{[Text.EncoderReplacementFallback]::new([string]::new([char[]][int[]]$templates[$encoder]))};$e.DecoderFallback=if($decoder -eq 5){[Text.DecoderExceptionFallback]::new()}else{[Text.DecoderReplacementFallback]::new([string]::new([char[]][int[]]$templates[$decoder]))};$values.Add($e);$profiles+=[ordered]@{kind='customized';emit=$emit;strict=$false;encoder=$encoder;decoder=$decoder}
}}}
$rows=@();foreach($left in 0..($values.Count-1)){foreach($right in 0..($values.Count-1)){$rows+=[ordered]@{left=$left;right=$right;equals=$values[$left].Equals($values[$right]);equalHashes=$values[$left].GetHashCode() -eq $values[$right].GetHashCode()}}
 $e=$values[$left];$hash=$e.GetHashCode();$sum=([long]$e.EncoderFallback.GetHashCode()+[long]$e.DecoderFallback.GetHashCode()+65001+[int]$profiles[$left].emit)-band 0xffffffffL;if($sum -ge 2147483648L){$sum-=4294967296L};$profiles[$left].hashFormulaMatches=$hash -eq $sum;$profiles[$left].hashStable=$hash -eq $e.GetHashCode();$profiles[$left].equalsClone=$e.Equals($e.Clone());$profiles[$left].cloneHashMatches=$hash -eq $e.Clone().GetHashCode();$profiles[$left].equalsNull=$e.Equals($null);$profiles[$left].equalsString=$e.Equals('UTF-8');$profiles[$left].equalsObject=$e.Equals([object]::new())
}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();replacementTemplates=$templates;profiles=$profiles;rows=$rows;qualification='SELECTED_UTF8_EQUALITY_AND_PROCESS_LOCAL_HASH_FORMULA_ONLY; NO_RAW_CROSS_PROCESS_HASH_EQUALITY_FULL_METADATA_SOURCE_ABI_OR_TASK_ACCEPTANCE'}
